        static PracticeFleetCandidates Case(string programs,PracticeMapStartup map,int id)
        {int local=id%80;return PracticeFleetCandidates.Create(programs,map,id/80,local/20,(local%20)/10==1,PracticeFleetCandidates.Distances[(local%10)/2],local%2);}
        static string Ids(PracticeFleetCandidates state){var values=new List<string>();foreach(int id in state.Candidates)values.Add(id.ToString());return string.Join("/",values.ToArray());}
        internal static void Run(Action<string,Action> check,Action<string,Action> evidence,string assets)
        {
            string root=Path.GetDirectoryName(assets),programs=Path.Combine(root,"Programs");Func<uint,PracticeMapStartup> map=delegate(uint seed){return PracticeMapStartup.CreateBssb202(programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),seed);};
            check("Fleet candidate scan matches twelve original519 complete endpoints",delegate
            {
                var startup=map(731);foreach(string line in Original)
                {
                    var r=line.Split(',');Need(r.Length==11,"519 golden columns");var c=Case(programs,startup,int.Parse(r[0]));
                    Need(c.Candidates.Count==int.Parse(r[1])&&c.TaskKind==int.Parse(r[2])&&c.SelectedWaypoint==int.Parse(r[3])&&c.RouteUiRequests==int.Parse(r[4])&&Hash(c.CopyShipPool())==r[5]&&Hash(c.CopyFleetPool())==r[6]&&Hash(c.CopyTaskRecord())==r[7]&&Hash(c.CopyScratchBytes())==r[8]&&Hash(c.CopyRawList())==r[9]&&Ids(c)==r[10],"Original519 endpoint "+r[0]);
                }
                Need(Original.Length==12,"Independent519 fixture count");
            });
            check("Candidate eligibility and active owner are supplied independently",delegate
            {
                var startup=map(731);var original=PracticeFleetCandidates.Create(programs,startup,0,0,false,-1,1);Need(original.EquipmentFound&&original.Candidates.Count==0&&original.TaskKind==0,"Original zero eligibility");
                var visible=PracticeFleetCandidates.Create(programs,startup,0,0,true,-1,1);Need(Ids(visible)=="26/25/24/23/15/14","Descending original order");var other=PracticeFleetCandidates.Create(programs,startup,0,0,true,-1,0);Need(other.Candidates.Contains(16),"Mismatched supplied active owner must retain source behavior including actor");
                var scenario=PracticeFleetCandidates.Create(programs,startup,10,0,true,-1,1);Need(Ids(scenario)=="16","Scenario8 actor-1 excludes owner0,not actor itself");
            });
            check("No-equipment candidate scan pushes service only outside kinds5 through8",delegate
            {
                var startup=map(731);var surface=PracticeFleetCandidates.Create(programs,startup,0,1,true,-1,1);Need(!surface.EquipmentFound&&surface.TaskKind==11&&surface.SelectedWaypoint==-1&&surface.RouteUiRequests==1&&surface.Candidates.Count==0,"No-equipment push11");
                var f=surface.CopyFleetPool();for(int n=0;n<5;n++)Need(BitConverter.ToInt16(f,16*492+40+n*2)==-1,"Route point not cleared");var t=surface.CopyTaskRecord();for(int n=260;n<296;n++)Need(t[n]==0x6d,"Opaque bytes changed");
                var stored=PracticeFleetCandidates.Create(programs,startup,2,1,true,-1,1);Need(!stored.EquipmentFound&&stored.TaskKind==0&&stored.SelectedWaypoint==3&&stored.RouteUiRequests==0,"Stored kind6 acquired service task");
            });
            check("Candidate raw scratch and zero range retain recovered sentinel behavior",delegate
            {
                var startup=map(731);var first=PracticeFleetCandidates.Create(programs,startup,0,2,true,0,1);var second=PracticeFleetCandidates.Create(programs,startup,0,3,true,32767,1);var metadata=File.ReadAllBytes(Path.Combine(programs,"EquipmentDispatchKinds.seqbin"));int weapon=1;while(metadata[weapon]!=0xf2&&metadata[weapon]!=0xf3)weapon++;
                Need(BitConverter.ToInt32(first.CopyScratchBytes(),weapon*4)==0&&BitConverter.ToInt32(second.CopyScratchBytes(),weapon*4)==1,"Roster index mapping");Need(BitConverter.ToInt32(first.CopyScratchBytes(),0)==-1&&BitConverter.ToInt16(File.ReadAllBytes(Path.Combine(programs,"AiCandidateRawRanges.seqbin")),0)==0&&Ids(first)==Ids(second),"Raw unmapped range0 case");
                Need(Ids(PracticeFleetCandidates.Create(programs,startup,1,0,true,-1,1))=="24","Kind2 alignment order changed");
            });
            check("Candidate results preserve source data and reject unsupported inputs",delegate
            {
                var startup=map(731);string before=Hash(startup.Stages[3].CopyShipPool())+Hash(startup.Stages[3].CopyFleetPool());var c=Case(programs,startup,31);var bytes=c.CopyTaskRecord();bytes[0]^=255;var f=c.CopyFleetPool();f[0]^=255;var s=c.CopyScratchBytes();s[0]^=255;
                Need(c.TaskKind==11&&c.CopyFleetPool()[0]!=f[0]&&c.CopyScratchBytes()[0]!=s[0]&&before==Hash(startup.Stages[3].CopyShipPool())+Hash(startup.Stages[3].CopyFleetPool()),"Mutable view or source escaped");
                Need(Reject(delegate{PracticeFleetCandidates.Create(programs,startup,-1,0,false,-1,1);})&&Reject(delegate{PracticeFleetCandidates.Create(programs,startup,11,0,false,-1,1);})&&Reject(delegate{PracticeFleetCandidates.Create(programs,startup,0,4,false,-1,1);})&&Reject(delegate{PracticeFleetCandidates.Create(programs,startup,0,0,false,2,1);})&&Reject(delegate{PracticeFleetCandidates.Create(programs,startup,0,0,false,-1,2);})&&Reject(delegate{PracticeFleetCandidates.Create(programs,map(0),0,0,false,-1,1);}),"Unsupported candidate factory input accepted");
                Need(Reject(delegate{PracticeFleetCandidates.Evaluate(new byte[0],new byte[123000],new byte[312],new byte[41],new byte[82],16,1,1);}),"Truncated candidate input accepted");
            });
            evidence("Candidate public factory matches all880 complete original519 cases",delegate
            {
                string folder=Path.Combine(root,"Evidence");var lines=File.ReadAllLines(Path.Combine(folder,"Fleet-Candidates-519.csv"));int count=0;
                using(var reader=new BinaryReader(File.OpenRead(Path.Combine(folder,"Fleet-Candidates-519.bin"))))
                {
                    Need(reader.ReadInt32()==0x35313943&&reader.ReadInt32()==1,"519 binary header");var startup=map(731);var baseS=startup.Stages[3].CopyShipPool();var baseF=startup.Stages[3].CopyFleetPool();
                    for(;;)
                    {
                        int id=reader.ReadInt32();if(id==-1)break;Need(id==count&&id<880,"519 case order");var fields=new int[8];for(int n=0;n<8;n++)fields[n]=reader.ReadInt32();
                        var beforeS=Delta(reader,baseS,268);var beforeF=Delta(reader,baseF,492);var beforeT=Read(reader,312);var afterS=Delta(reader,beforeS,268);var afterF=Delta(reader,beforeF,492);var afterT=Read(reader,312);var scratch=Read(reader,164);var list=Read(reader,1008);int sf=reader.ReadInt32(),su=reader.ReadInt32(),wp=reader.ReadInt32();var requests=new uint[4];for(int n=0;n<4;n++)requests[n]=reader.ReadUInt32();
                        var c=Case(programs,startup,id);Need(c.Actor==fields[0]&&c.ActorKind==fields[1]&&c.ParentCategory==fields[2]&&c.Scenario==fields[3]&&c.EquipmentProfile==fields[4]&&(c.SuppliedEligibility?1:0)==fields[5]&&c.DistanceProfile==fields[6]&&c.ActiveOwner==fields[7],"519 supplied inputs "+id);
                        Need(Hash(c.CopyShipPool())==Hash(afterS)&&Hash(c.CopyFleetPool())==Hash(afterF)&&Hash(c.CopyTaskRecord())==Hash(afterT)&&Hash(c.CopyScratchBytes())==Hash(scratch)&&Hash(c.CopyRawList())==Hash(list),"519 complete data "+id);
                        Need(Hash(beforeT)==Hash(PracticeFleetServiceContext.CreateDiagnostic(c.Actor))&&sf==c.Actor&&su==30&&wp==c.SelectedWaypoint&&requests[0]==0&&requests[1]==0&&requests[2]==0&&requests[3]==c.RouteUiRequests,"519 context/scalars "+id);
                        var row=lines[id+1].Split(',');Need(row.Length==23&&int.Parse(row[0])==id&&int.Parse(row[9])==c.Candidates.Count&&row[18]==Hash(afterS)&&row[19]==Hash(afterF)&&row[21]==Hash(scratch)&&row[22]==Hash(list),"519 independentCSV "+id);count++;
                    }
                    Need(count==880&&lines.Length==881&&reader.BaseStream.Position==reader.BaseStream.Length,"519 matrix/trailing bytes");
                }
            });
        }
        static byte[] Read(BinaryReader reader,int length){var bytes=reader.ReadBytes(length);if(bytes.Length!=length)throw new EndOfStreamException("519 truncated evidence");return bytes;}
        static byte[] Delta(BinaryReader reader,byte[] basis,int stride)
        {
            var bytes=(byte[])basis.Clone();int count=reader.ReadUInt16(),last=-1;if(count>bytes.Length/stride)throw new InvalidDataException("519 delta count");for(int n=0;n<count;n++){int slot=reader.ReadUInt16();if(slot<=last||slot>=bytes.Length/stride)throw new InvalidDataException("519 delta slot");last=slot;Read(reader,stride).CopyTo(bytes,slot*stride);}return bytes;
        }
    }
